def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return:
    """
    try:
        return {"days": value.days, "seconds": value.seconds, "microseconds": value.microseconds}
    except AttributeError:
        raise TypeError("Invalid type for dehydration: {}".format(type(value)))

def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if not isinstance(value, Time):
        raise TypeError("Value must be a Time object")
    return value.isoformat()

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if not isinstance(value, Point):
        raise TypeError("Value must be a Point")
    return {
        "x": value.x,
        "y": value.y,
        "z": value.z
