def parse_version(s: str) -> tuple[int, ...]:
    """
    Poor man's version comparison

    :param s: A string representing a version number in the format "major.minor.patch"
    :return: A tuple of integers representing the major, minor, and patch versions
    """
    try:
        major, minor, patch = s.split(".")
