def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Check if all digests in manifest are present
    for manifest_file in manifest_files:
        if manifest_file.digest not in digests_used:
            raise ValueError(f"Digest {manifest_file.digest} is not present in the manifest.")

    # Check if all digests used are present in the manifest
    for digest in digests_used:
        if digest not in manifest_files:
            raise ValueError(f"Digest {digest} is not present in the manifest.")

    return True

