def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    result = []
    for expr in args:
        if expr.op == '&':
            if expr.left.op == '|' and expr.left.right == expr.right:
                result.append(expr.left.left)
            elif expr.right.op == '|' and expr.right.right == expr.left:
                result.append(expr.right.left)
        elif expr.op == '|':
            if expr.left.op == '&' and expr.left.right == expr.right:
                result.append(expr.left.left)
            elif expr.right.op == '&' and expr.right.right == expr.left:
                result.append(expr.right.left)
        else:
            result.append(expr)
    return result
