def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None

    try:
        number, unit = frequency.split()
        number = int(number)
        if unit == "week":
            return datetime.timedelta(weeks=number)
        elif unit == "day":
            return datetime.timedelta(days=number)
        elif unit == "hour":
            return datetime.timedelta(hours=number)
        elif unit == "minute":
            return datetime.timedelta(minutes=number)
        elif unit == "second":
            return datetime.timedelta(seconds=number)
        else:
            raise ValueError(f"Invalid unit of time: {unit}")
    except ValueError:
        raise ValueError(f"Invalid frequency: {frequency}")

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    name, default = matcher.group(1), matcher.group(2)
    value = os.environ.get(name)
    if value is None:
        if default is None:
            raise Error(f"Environment variable {name} is not defined and no default value was provided.")
        else:
            value = default
    return value

